<template>
  <div class="groups-redesign">
    <!-- Section 1: Top toggle bar -->
    <div class="groups-toggle-bar">
      <span>{{ $t('group_main_setting') }}</span>
      <f-toggle
        class="ml-10"
        size="xs"
        v-model="user_settings['GROUP_PERMISSION_ACTIVATED']"
        @update:model-value="
          (val: any) => {
            saveSetting('GROUP_PERMISSION_ACTIVATED', val);
          }
        "
      />
    </div>

    <!-- Section 2 & 3: Panels (left navigator + right details) -->
    <div v-if="groupPermissionEnabled" class="groups-panels" data-test="groups-panels">
      <div class="groups-sidebar">
        <GroupNavigator
          ref="navigator"
          :groups="groups"
          :selectedGroupId="selectedGroup?.group_id || null"
          :loading="processing"
          @group-selected="handleGroupSelected"
          @edit-group="handleEditGroup"
          @view-access-control="handleViewAccessControl"
          @delete-group="handleDeleteGroup"
          @group-edited="handleGroupEdited"
        />
      </div>
      <div class="groups-main">
        <div v-if="selectedGroup" class="groups-content">
          <GroupDetails
            :group="selectedGroup"
            @close="handleCloseDetails"
            @edit-group="handleEditGroup"
            @view-access-control="handleViewAccessControl"
            @delete-group="handleDeleteGroupRequest"
          />
        </div>
        <div v-else class="empty-state" data-test="groups-detail-placeholder">
          <q-icon name="group" size="64px" color="grey-4" class="q-mb-md" />
          <p class="text-grey-6">{{ $t('select_group_to_view_details') }}</p>
        </div>
      </div>
    </div>
  </div>
</template>

<script lang="ts">

import { storeToRefs } from 'pinia';
import { computed, defineComponent } from 'vue';
import { Acl } from 'src/core/acls/index';
import { toBoolPreference } from 'src/utils/preferenceBool';
import GroupDetails from './GroupDetails.vue';
import GroupNavigator from './GroupNavigator.vue';
import type { dynamicObj } from 'src/pages/assets';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';
import { useDocPermissionsStore, useSettingStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';

export default defineComponent({
  name: 'Groups',
  mixins: [helperMixin],
  components: {
    GroupNavigator,
    GroupDetails,
  },

  setup() {
    const permission_store = useDocPermissionsStore();
    const { processing, groups } = storeToRefs(permission_store);
    const { getPermissionsData, deleteGroupById } = permission_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting } = settings_store;

    // Normalize the raw pref value (may arrive as the string "0"/"false")
    // so the panel visibility matches Acl.ts's own enforcement of this key
    // (DRFS-626). Without this the panels showed while ACLs treated the
    // group permission as disabled.
    const groupPermissionEnabled = computed(() =>
      toBoolPreference(user_settings.value['GROUP_PERMISSION_ACTIVATED']),
    );

    return {
      processing,
      groups,
      getPermissionsData,
      deleteGroupById,
      updateSetting,
      user_settings,
      groupPermissionEnabled,
    };
  },

  data() {
    return {
      selectedGroup: null as any,
    };
  },

  watch: {
    processing(active) {
      active ? this.showLoading() : this.hideLoading();
    },
  },

  mounted() {
    if (this.processing) {
      this.showLoading();
    }
    this.initView();
  },

  methods: {
    async initView() {
      try {
        this.processing = true;
        if (!this.user_settings['GROUP_PERMISSION_ACTIVATED']) {
          this.user_settings['GROUP_PERMISSION_ACTIVATED'] = false;
        }
        await this.getPermissionsData();
        this.applyPreselectedGroup();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    applyPreselectedGroup() {
      const requestedId = this.$route.query.selectedGroupId;
      if (!requestedId) return;
      const match = this.groups.find(
        (g: any) => String(g.group_id) === String(requestedId),
      );
      if (match) {
        this.selectedGroup = match;
      } else {
        notify.info(this.$t('group_no_longer_available'));
      }
    },

    async saveSetting(key: string, value: any) {
      try {
        this.processing = true;
        await this.updateSetting(key, value);
        await Acl.refresh();
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    handleGroupSelected(group: any) {
      if (this.selectedGroup?.group_id === group.group_id) {
        this.selectedGroup = null;
      } else {
        this.selectedGroup = group;
      }
    },

    handleCloseDetails() {
      this.selectedGroup = null;
    },

    handleEditGroup(group: any) {
      const navigator = this.$refs.navigator as any;
      if (navigator?.openEditDialog) {
        navigator.openEditDialog(group);
      }
    },

    handleDeleteGroupRequest(group: any) {
      // Route delete clicks from the details header through the navigator's
      // confirmation dialog so the flow is identical to the context menu.
      const navigator = this.$refs.navigator as any;
      if (navigator?.confirmDeleteGroup) {
        navigator.confirmDeleteGroup(group);
      }
    },

    handleViewAccessControl(group: any) {
      this.$router.push(
        `/settings/access-control/${group.group_name}/${group.group_id}`,
      );
    },

    async handleDeleteGroup(group: any) {
      try {
        this.processing = true;
        await this.deleteGroupById(group.group_id);

        if (this.selectedGroup?.group_id === group.group_id) {
          this.selectedGroup = null;
        }
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.processing = false;
      }
    },

    handleGroupEdited() {
      // Store already updated by CreateGroup; refresh selection so the
      // details pane picks up the new name/description.
      if (!this.selectedGroup) return;
      const updated = this.groups.find(
        (g: any) => g.group_id === this.selectedGroup.group_id,
      );
      if (updated) this.selectedGroup = updated;
    },
  },
});
</script>

