<template>
  <q-card class="menu-tabs-card back-white q-mt-md" data-test="menu-tabs-card">
    <q-card-section class="menu-tabs-section">
      <div class="text-subtitle1 text-weight-medium q-mb-xs card-title">
        <q-icon name="tab" class="q-mr-sm" />
        {{ $t('menu_tabs_section_title') }}
      </div>

      <div
        class="text-caption menu-tabs-hint q-mb-md"
        data-test="menu-tabs-hint"
      >
        {{ $t('menu_tabs_hint') }}
      </div>

      <div class="menu-tabs-list">
        <q-checkbox
          v-for="tab in gateableTabs"
          :key="tab.feature_key"
          :model-value="isEnabled(tab.feature_key)"
          :label="$t(tab.label_key)"
          :disable="saving || loading"
          :data-feature-key="tab.feature_key"
          :data-test="`menu-tab-${tab.feature_key}`"
          class="menu-tab-checkbox"
          @update:model-value="
            (val: boolean) => toggleTab(tab.feature_key, val)
          "
        />
      </div>

      <q-inner-loading :showing="loading">
        <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
      </q-inner-loading>
    </q-card-section>
  </q-card>
</template>

<script lang="ts">
/**
 * "Which menu tabs may this role see?" — DOCB-14282.
 *
 * Sits in the role detail pane on Settings -> Roles. The page calls these
 * "Roles"; the entity it manages is the backend GROUP, so `groupId` here is a
 * `group_cache.id` and that is what gets stored in
 * `feature_access_control.entity_id`.
 *
 * ## The inversion
 *
 * The API is per-FEATURE ("which roles may see this tab"), because that is the
 * shape the enforcement gate reads on every request. This component is
 * per-ROLE, because that is the question an admin is asking while looking at
 * one role. So a save reads the feature's current role list, adds or removes
 * just this role, and PUTs the whole list back.
 *
 * That read-modify-write is why the save is not a blind PUT: two admins on two
 * roles at the same time would otherwise have the second one erase the first
 * one's grant, silently. Re-reading immediately before writing keeps the
 * window to the length of one request instead of the length of a page visit.
 *
 * ## Adding a tab
 *
 * One entry in `GATEABLE_MENU_TABS` (`src/utils/analytics-access.ts`). This
 * component renders whatever is in that array — there is nothing to change
 * here.
 */
import { defineComponent } from 'vue';
import { notify } from 'src/components/notifications/notify';
import { ApiExceptions } from 'src/exceptions/index';
import type { dynamicObj } from 'src/pages/assets';
import { GATEABLE_MENU_TABS } from 'src/utils/analytics-access';
import { invalidateAnalyticsAccess } from 'src/composables/useAnalyticsAccess';

export default defineComponent({
  name: 'MenuTabAccess',

  props: {
    /**
     * The role being edited. Named `groupId` rather than `roleId` to match
     * what the backend actually stores — the UI label and the data model
     * disagree here, and hiding that in a prop name is how the two drift.
     */
    groupId: {
      type: String,
      required: true,
    },
  },

  data() {
    return {
      gateableTabs: GATEABLE_MENU_TABS,
      /** feature_key -> the role ids currently granted it, as loaded. */
      grantsByFeature: {} as Record<string, string[]>,
      loading: false,
      saving: false,
    };
  },

  watch: {
    // Selecting a different role in the navigator reuses this component, so
    // the grants have to be re-read; otherwise the checkboxes would keep
    // showing the previous role's state.
    groupId: {
      immediate: true,
      handler() {
        void this.loadGrants();
      },
    },
  },

  methods: {
    isEnabled(featureKey: string): boolean {
      const granted = this.grantsByFeature[featureKey] || [];
      return granted.some((id) => String(id) === String(this.groupId));
    },

    async loadGrants() {
      this.loading = true;
      try {
        const { documentPermissionsApiService } = await import('src/services');
        const results = await Promise.all(
          this.gateableTabs.map((tab) =>
            documentPermissionsApiService.getFeatureAccess(tab.feature_key),
          ),
        );
        const next: Record<string, string[]> = {};
        this.gateableTabs.forEach((tab, index) => {
          const entityIds = results[index]?.entity_ids;
          next[tab.feature_key] = Array.isArray(entityIds)
            ? entityIds.map((id: unknown) => String(id))
            : [];
        });
        this.grantsByFeature = next;
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async toggleTab(featureKey: string, enabled: boolean) {
      if (this.saving || !this.groupId) return;
      const editedGroupId = this.groupId;
      this.saving = true;
      try {
        const { documentPermissionsApiService } = await import('src/services');

        // Re-read before writing. The endpoint replaces the whole list, so
        // saving a stale one would revoke a grant another admin just made.
        const current =
          await documentPermissionsApiService.getFeatureAccess(featureKey);
        // A failed read is not an empty grant list: PUT would revoke every
        // other group's access if we silently treated an error as [].
        if (current?.success === false || !Array.isArray(current?.entity_ids)) {
          throw current || new Error('Invalid feature access response');
        }
        const existing: string[] = Array.isArray(current?.entity_ids)
          ? current.entity_ids.map((id: unknown) => String(id))
          : [];

        const withoutThisRole = existing.filter(
          (id) => String(id) !== String(editedGroupId),
        );
        const nextIds = enabled
          ? [...withoutThisRole, String(editedGroupId)]
          : withoutThisRole;

        const saved = await documentPermissionsApiService.setFeatureAccess(
          featureKey,
          nextIds,
        );

        if (saved?.success === false || !Array.isArray(saved?.entity_ids)) {
          throw saved || new Error('Invalid feature access response');
        }

        // Trust the echo, not the request: the server de-duplicates and drops
        // blanks, so what it returns is what is actually stored.
        const storedIds = Array.isArray(saved?.entity_ids)
          ? saved.entity_ids.map((id: unknown) => String(id))
          : nextIds;
        this.grantsByFeature = {
          ...this.grantsByFeature,
          [featureKey]: storedIds,
        };

        // The side menu and the route guard hold this list; without the
        // invalidation the admin would have to reload before seeing the icon
        // appear or disappear for themselves.
        invalidateAnalyticsAccess();

        notify.success(this.$t('saved_successfully'));
      } catch (err) {
        // The server's own message, like every sibling component on this
        // page — no bespoke fallback key (see the note on the hint above).
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
        // Re-read so a failed toggle does not leave the checkbox showing a
        // state the server never accepted.
        await this.loadGrants();
      } finally {
        this.saving = false;
      }
    },
  },
});
</script>

